const $=s=>document.querySelector(s),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));let tools=[];
fetch('studio/tools.json').then(r=>r.json()).then(data=>{tools=data;$('#tools').innerHTML=data.map((t,i)=>`<article class="card"><span class="label">0${i+1} / ${esc(t.type)}</span><h3>${esc(t.name)}</h3><span class="status ${t.status==='已实接'?'':'pending'}">${esc(t.status)}</span><p>${esc(t.use)}</p><p>${esc(t.limit)}</p><p>${esc(t.version)}</p>${t.url?`<a href="${esc(t.url)}" target="_blank" rel="noopener">官方依据 ↗</a>`:'<p>待补充原视频 / 唯一仓库地址</p>'}</article>`).join('');}).catch(()=>$('#tools').textContent='工具资料加载失败，请刷新重试。');
document.querySelectorAll('[data-demo]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-demo]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));$('#tool-frame').src='studio/demo.html?tool='+b.dataset.demo;$('#demo-description').textContent=tools.find(t=>t.id===b.dataset.demo)?.use||'工具试验台';});
fetch('studio/workflow.json').then(r=>r.json()).then(data=>{$('#workflow').innerHTML=data.map((x,i)=>`<article><strong>0${i+1}</strong><h3>${esc(x.role)}</h3><p>${esc(x.result)}</p><button data-prompt="${i}">复制工作提示词</button></article>`).join('');document.querySelectorAll('[data-prompt]').forEach(b=>b.onclick=async()=>{try{await navigator.clipboard.writeText(data[+b.dataset.prompt].prompt);$('#toast').textContent='已复制工作提示词';}catch{$('#toast').textContent='复制未成功，请下载 JSON 保存提示词';}setTimeout(()=>$('#toast').textContent='',2500);});});
